#!/bin/bash
set -e
mkdir -p /opt/hw4
base64 -d > /opt/hw4/reporter.py <<'PYCODE'

PYCODE

cat > /etc/systemd/system/hw4-reporter.service <<'EOF'
[Unit]
Description=HW4 Country Reporter
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/opt/hw4
ExecStart=/usr/bin/python3 -u /opt/hw4/reporter.py
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable --now hw4-reporter
